WITH with_gaps AS (SELECT *, CASE WHEN LAG(event_time) OVER (PARTITION BY session_id ORDER BY event_time, id) IS NULL OR event_time > LAG(event_time) OVER (PARTITION BY session_id ORDER BY event_time, id) + INTERVAL 7 DAYS THEN 1 ELSE 0 END AS session_start_flag FROM web_events), islands AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY session_id ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id_2 FROM with_gaps) SELECT id, session_id, page, duration_sec, session_start_flag, session_id_2 FROM islands ORDER BY page DESC, session_start_flag
